  "regulated_action": {
    "target_id": "t0",
    "description": "Transfer patient pt_4471 to a pharmacist for refill of controlled substance rx_60092 (oxycodone 5 mg, C-II)."
  },
  "applicable_norms": [
    {
      "policy_source_id": "q23",
      "interpretation": "Controlled substances (schedule C-II) can never be refilled through the assistant channel; the patient must be transferred to a pharmacist.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q23",
      "interpretation": "Transfer to a pharmacist is mandatory only for controlled substances (C-II) or clinical questions.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q23",
      "interpretation": "Before any action that changes data (e.g., refill), explicit user confirmation must be obtained.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h37",
      "actor": "assistant",
      "role": "system",
      "fact": "Prescription rx_60092 has `schedule: C-II` (controlled substance)."
    },
    {
      "source_id": "h35",
      "actor": "user",
